{
  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])

    nodes_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        children.setdefault(n['id'], [])
        if n['parent'] is not None:
            children.setdefault(n['parent'], []).append(n['id'])

    retained = set(nodes_map.keys())
    symbol_to_ids = {}
    for n in nodes:
        symbol_to_ids.setdefault(n['symbol'], set()).add(n['id'])

    order = []
    sorted_ids = sorted(nodes_map.keys(), key=lambda nid: (-nodes_map[nid]['depth'], nid))

    for nid in sorted_ids:
        node = nodes_map[nid]
        if nid == 'root':
            continue
        if node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        has_retained_child = any(c in retained for c in children.get(nid, []))
        if has_retained_child:
            continue
        ok = True
        for req in required_symbols:
            if node['symbol'] == req and len(symbol_to_ids.get(req, set())) == 1:
                ok = False
                break
        if ok:
            order.append(nid)
            retained.remove(nid)
            symbol_to_ids[node['symbol']].remove(nid)

    retained = sorted(retained)
    return {'retained': retained, 'removal_order': order}"
}
